import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:suite @smoke Back button during form interaction', async ({ page }) => {
  await opGoto(page, '/')
  await opClick(page, 'button', 'Try it out')
  await opFill(page, 'petId', '99999')
  await opClick(page, 'button', 'Execute')
  await opClick(page, 'button', 'Back')
  await opSeen(page, 'heading', 'POST /pet')
})
